package ru.evolenta.pgs.worker;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import static ru.evolenta.pgs.worker.Util.*;

/** Executes actual Java import/rollback against a deterministic in-memory PGS adapter. */
public final class AdvertisingAcceptanceFaultTest {
    private static int passed;
    private static void check(boolean b,String message){if(!b)throw new AssertionError(message);passed++;}
    public static void main(String[]args)throws Exception{
        Map<String,Object>fixture=map(Json.parse(new String(Files.readAllBytes(Paths.get(args[0])),StandardCharsets.UTF_8)));Path root=Paths.get(args[1]);Files.createDirectories(root);
        String selected=args.length>2?args[2]:"all";if(!Arrays.asList("all","normal","active","uncertain","omsu","changed","batch").contains(selected))throw new IllegalArgumentException("Unknown scenario");
        if(selected.equals("all")||selected.equals("normal"))scenario(fixture,root.resolve("normal"),false,false,false,false);if(selected.equals("all")||selected.equals("active"))scenario(fixture,root.resolve("active"),true,false,false,false);if(selected.equals("all")||selected.equals("uncertain"))scenario(fixture,root.resolve("uncertain"),false,true,false,false);if(selected.equals("all")||selected.equals("omsu"))scenario(fixture,root.resolve("omsu"),false,false,true,false);if(selected.equals("all")||selected.equals("changed"))scenario(fixture,root.resolve("changed"),false,false,false,true);if(selected.equals("all")||selected.equals("batch"))batchScenario(fixture,root.resolve("batch"));
        System.out.println("PASS import/rollback "+passed+" assertions");
    }
    private static Command command(Fake p,boolean rollback,Command.Operation operation){Map<String,Object>v=obj();for(Map.Entry<String,Object>e:obj("mainId",rollback?"rollback":p.mainId,"collectionName","rbuModulesAppeals.subservices","camundaBusinessInfoId",rollback?"rb-info":"info","rbuDomain","ADVERTISING","rbuProfile",p.profile,"rbuOperation",operation.name(),"rbuContractVersion","1").entrySet())v.put(e.getKey(),obj("type","String","value",e.getValue()));return new Command(obj("id",operation.name()+"-task","processInstanceId",rollback?"rb-process":"process","activityId",operation.name(),"variables",v));}
    private static void scenario(Map<String,Object>fixture,Path dir,boolean active,boolean uncertain,boolean omsu,boolean changed)throws Exception{
        try(Journal j=new Journal(dir)){Fake p=new Fake(fixture);p.profile=omsu?"OMSU":"ROIV";Context c=new Context(command(p,false,Command.Operation.IMPORT_APPLY),p);Map<String,Object>d=map(c.appeal.get("importDraft"));String validationKey=hash("fixture-validation");d.put("workerValidationKey",validationKey);Map<String,Object>publicDraft=Operations.compactDraft(d);p.cases.get(p.mainId).put("importDraft",publicDraft);j.save(validationKey,obj("processId","process","appealId",p.mainId,"inputHash",ImportOperations.inputHash(publicDraft),"draft",d));Operations ops=new Operations(j,()->{},true,"https://test.example");p.failAfterCommit=uncertain;
            if(uncertain){boolean failed=false;try{ops.execute(new Context(command(p,false,Command.Operation.IMPORT_APPLY),p));}catch(java.io.IOException expected){failed=true;}check(failed,"Simulated timeout after committed CREATE");}
            Map<String,Object>result=ops.execute(new Context(command(p,false,Command.Operation.IMPORT_APPLY),p));check(!bool(result.get("rbuApplyHasMoreBatches")),"All fixture records applied");check(p.created==10,"5 source rows create exactly 10 physical records");check(integer(result.get("rbuCreatedRows"))==5,"Counter counts source rows, not inner stages");check(p.records.keySet().equals(new HashSet<String>(Arrays.asList("placeReestrRKCollection","nsiUnifiedPGS_object_marketing","biddingReestrRKCollection","contractReestrRKCollection","obligationReestrRKCollection","marketingLicenses","marketingRegistry","socialAdReestrRKCollection","unauthorizedReestrRKCollection","dismantleReestrRKCollection"))),"Every expected target collection is present");for(Map<String,Map<String,Object>> collection:p.records.values())check(collection.size()==1,"One physical record per collection for the five-row fixture");int creates=p.created;ops.execute(new Context(command(p,false,Command.Operation.IMPORT_APPLY),p));check(p.created==creates,"Repeated application never duplicates records");ops.execute(new Context(command(p,false,Command.Operation.IMPORT_FINALIZE),p));
            Map<String,Object>sub=maps(p.cases.get(p.mainId).get("subservices")).get(0);check(list(sub.get("migrationCreatedRecords")).size()==10,"Full migration journal persisted");Map<String,Object>place=p.records.get("placeReestrRKCollection").values().iterator().next();check("@id:sheet2:6:place".equals(at(place,"infoRK.addressData")),"User text cannot become an internal record reference");check(present(at(place,"infoRK.urlEPGU"))&&present(at(place,"biddingInfo.biddingNumber")),"Cross-links applied");for(Map<String,Object>registry:p.records.get("marketingRegistry").values())check(p.records.get("marketingLicenses").containsKey(clean(registry.get("licenseId"))),"Registry links to created license");
            Files.write(dir.resolve("records-before-rollback.json"),Json.write(p.records).getBytes(StandardCharsets.UTF_8));
            if(active)p.activeCases.add(obj("_id","active-case","status",obj("code","process"),"objects",Arrays.asList(obj("_id",id(place)))));
            p.createRollback();String rollbackOwner=clean(p.cases.get("rollback").get("unitId"));p.cases.get("rollback").put("unitId","different-organization");boolean foreignRejected=false;try{ops.execute(new Context(command(p,true,Command.Operation.ROLLBACK_PREPARE),p));}catch(IllegalArgumentException expected){foreignRejected=true;}check(foreignRejected&&p.deleted==0,"Foreign organization cannot prepare rollback");p.cases.get("rollback").put("unitId",rollbackOwner);ops.execute(new Context(command(p,true,Command.Operation.ROLLBACK_PREPARE),p));Map<String,Object>rbSub=maps(p.cases.get("rollback").get("subservices")).get(0),plan=map(rbSub.get("rbuRollbackPlan"));check(integer(plan.get("totalRecords"))==10,"Rollback plan reads exact migration journal");if(active)check(integer(plan.get("blockedRecords"))>=3,"Active reference blocks all records of its source row");else check(integer(plan.get("deletableRecords"))==10,"All unchanged unreferenced records are deletable");
            if(changed)Util.put(place,"infoRK.numberRK","changed-after-preparation");for(Map<String,Object> forged:maps(plan.get("items")))forged.put("state","DELETED");p.failDeleteAfterCommit=uncertain;p.cases.get("rollback").put("rbuRollbackDecision",obj("confirmed",true,"targetAppealId",p.mainId,"journalFingerprint",plan.get("journalFingerprint")));ops.execute(new Context(command(p,true,Command.Operation.ROLLBACK_EXECUTE),p));ops.execute(new Context(command(p,true,Command.Operation.ROLLBACK_FINALIZE),p));String status=clean(at(p.cases.get("rollback"),"rollbackResultStatus"));check(status.equals(active||changed?"PARTIAL":"ROLLED_BACK"),"Correct rollback outcome");if(active||changed)check(p.records.get("placeReestrRKCollection").containsKey(id(place)),"Referenced parent remains in registry");else check(p.deleted==10,"Every journal record deleted exactly once");int deletes=p.deleted;ops.execute(new Context(command(p,true,Command.Operation.ROLLBACK_EXECUTE),p));check(p.deleted==deletes,"Repeated rollback never repeats successful deletes");Files.write(dir.resolve("records-after-rollback.json"),Json.write(p.records).getBytes(StandardCharsets.UTF_8));Files.write(dir.resolve("result.json"),Json.write(obj("scenario",dir.getFileName().toString(),"created",p.created,"deleted",p.deleted,"rollbackStatus",status,"report",rbSub.get("rbuRollbackReport"))).getBytes(StandardCharsets.UTF_8));
            Map<String,Object>oldSummary=map(sub.get("advertisingMigrationSummary"));p.cases.get(p.mainId).remove("migrationRollback");oldSummary.remove("workerContract");p.createRollback();boolean oldRejected=false;try{ops.execute(new Context(command(p,true,Command.Operation.ROLLBACK_PREPARE),p));}catch(IllegalArgumentException expected){oldRejected=true;}check(oldRejected,"Legacy import without worker marker rejected by Java");
        }
    }
    private static void batchScenario(Map<String,Object>fixture,Path dir)throws Exception{Map<String,Object>expanded=copy(fixture);for(Map<String,Object>s:maps(at(expanded,"importDraft.sheets"))){List<Object>rows=new ArrayList<Object>();List<Map<String,Object>>base=maps(s.get("rows"));for(int n=0;n<10;n++)for(Map<String,Object>r:base){Map<String,Object>x=copy(r);x.put("rowNumber",rows.size()+6);rows.add(x);}s.put("rows",rows);}map(expanded.get("importDraft")).put("validRows",50);try(Journal j=new Journal(dir)){Fake p=new Fake(expanded);Map<String,Object>draft=map(p.cases.get(p.mainId).get("importDraft"));String key=hash("batch-validation");draft.put("workerValidationKey",key);Map<String,Object>publicDraft=Operations.compactDraft(draft);p.cases.get(p.mainId).put("importDraft",publicDraft);j.save(key,obj("processId","process","appealId",p.mainId,"inputHash",ImportOperations.inputHash(publicDraft),"draft",draft));Operations ops=new Operations(j,()->{},true,"https://test.example");int rounds=0;Map<String,Object>result;do{result=ops.execute(new Context(command(p,false,Command.Operation.IMPORT_APPLY),p));rounds++;check(rounds<10,"Batch loop terminates");}while(bool(result.get("rbuApplyHasMoreBatches")));check(rounds==2,"100 records require two packets");check(p.created==100,"No records lost across packet boundaries");check(integer(result.get("rbuApplyRowCursor"))==100,"Final cursor is physical record count");ops.execute(new Context(command(p,false,Command.Operation.IMPORT_FINALIZE),p));Files.write(dir.resolve("result.json"),Json.write(obj("rounds",rounds,"physicalRecords",p.created,"finalVariables",result)).getBytes(StandardCharsets.UTF_8));}}
    private static final class Fake implements PgsApi{
        final Map<String,Map<String,Object>>cases=new HashMap<String,Map<String,Object>>();final Map<String,Map<String,Map<String,Object>>>records=new HashMap<String,Map<String,Map<String,Object>>>();final List<Map<String,Object>>activeCases=new ArrayList<Map<String,Object>>();final String mainId;Map<String,Object>organization;int created,deleted;boolean failAfterCommit,failDeleteAfterCommit;String profile="ROIV";
        Fake(Map<String,Object>fixture){Map<String,Object>appeal=copy(fixture);mainId=id(appeal);organization=copy(map(appeal.get("organization")));organization.put("inn","7706281123");Map<String,Object>draft=map(appeal.get("importDraft"));Map<String,Object>file=map(draft.get("file"));file.put("sha256",sha("fixture".getBytes(StandardCharsets.UTF_8)));draft.put("validatedFileSha256",file.get("sha256"));for(Map<String,Object>sheet:maps(draft.get("sheets")))if("sheet2".equals(sheet.get("code")))for(Map<String,Object>row:maps(sheet.get("rows")))for(Map<String,Object>cell:maps(row.get("cells")))if("Дополнительные данные об адресе".equals(cell.get("fieldName")))cell.put("value","@id:sheet2:6:place");for(Map<String,Object>sheet:maps(draft.get("sheets")))if("sheet2".equals(sheet.get("code")))for(Map<String,Object>column:maps(sheet.get("columns")))if("Дополнительные данные об адресе".equals(column.get("fieldName")))for(Map<String,Object>row:maps(sheet.get("rows"))){boolean found=false;for(Map<String,Object>cell:maps(row.get("cells")))if(column.get("column").equals(cell.get("column"))){cell.put("value","@id:sheet2:6:place");found=true;}if(!found){Map<String,Object>cell=copy(column);cell.put("value","@id:sheet2:6:place");list(row.get("cells")).add(cell);}}draft.put("status","VALIDATED");draft.put("validationBlocked",false);draft.put("parserVersion","adv-java-1.0-photo");draft.put("context",obj("region","Ростовская область","municipality","г. Ростов-на-Дону","organization",organization,"regionId","region","municipalityId","municipality","organizationCardId","card"));appeal.put("region",obj("_id","region"));appeal.put("municipality",obj("_id","municipality"));appeal.put("status",obj("code","complete"));Map<String,Object>sub=maps(appeal.get("subservices")).get(0);sub.put("camundaProcessInfo",obj("id","process","camundaBusinessInfoId","info"));sub.put("rbuImportDraft",draft);sub.put("xsdData",obj("rbuImportConfirmation",obj("confirmApply",true)));sub.remove("migrationCreatedRecords");sub.remove("advertisingMigrationSummary");appeal.put("subservices",Arrays.asList(sub));cases.put(mainId,appeal);}
        void createRollback(){cases.put("rollback",obj("_id","rollback","guid","rollback-guid","number","ROLLBACK-TEST","unit",map(cases.get(mainId).get("unit")),"unitId",first(cases.get(mainId).get("unitId"),at(cases.get(mainId),"unit.id")),"migrationCase",obj("_id",mainId),"subservices",Arrays.asList(obj("guid","rb-sub","parentEntries","rbuModulesAppeals.subservices","camundaProcessInfo",obj("id","rb-process","camundaBusinessInfoId","rb-info"),"xsdData",obj()))));}
        public Map<String,Object>find(String c,String id){if(c.equals("rbuModulesAppeals"))return copy(cases.getOrDefault(id,obj()));if(c.equals("organizations"))return copy(organization);if(c.equals("rbuRegionMunicipalAdvert"))return obj("_id","card","organizationGuid",organization.get("guid"),"passport",obj("_id","region"),"municipality",obj("_id","municipality"),"isMigration",true);if(c.equals("rbuRegionPassportsMarketing"))return obj("_id","region","regionName","Ростовская область");if(c.equals("rbuRegionMunicipalitiesMarketing"))return obj("_id","municipality","municipalityName","г. Ростов-на-Дону","passportId","region");return copy(records.getOrDefault(c,Collections.emptyMap()).getOrDefault(id,obj()));}
        public List<Map<String,Object>>search(String c,List<Object>filters,int page,int size){if(c.equals("organizations"))return Arrays.asList(copy(organization));if(c.equals("marketingAppeals"))return page==0?new ArrayList<Map<String,Object>>(activeCases):Collections.emptyList();List<Map<String,Object>>out=new ArrayList<Map<String,Object>>();for(Map<String,Object>record:records.getOrDefault(c,Collections.emptyMap()).values()){boolean ok=true;for(Object f:filters){Map<String,Object>filter=map(f);if(filter.containsKey("field"))ok&=clean(at(record,clean(filter.get("field")))).equals(clean(filter.get("value")));}if(ok)out.add(copy(record));}int start=Math.min(out.size(),page*size);return out.subList(start,Math.min(out.size(),start+size));}
        public void update(String c,String id,String guid,Map<String,Object>patch){if(c.equals("rbuModulesAppeals"))cases.get(id).putAll(copy(patch));else records.get(c).get(id).putAll(copy(patch));}
        public void updateSub(String c,String id,String guid,String parent,Map<String,Object>patch){for(Map<String,Object>s:maps(cases.get(id).get("subservices")))if(guid.equals(s.get("guid")))s.putAll(copy(patch));}
        public Map<String,Object>create(String c,Map<String,Object>payload)throws Exception{Map<String,Object>record=copy(payload);String id=present(record.get("_id"))?clean(record.get("_id")):String.format("%024x",created+1);record.put("_id",id);Map<String,Map<String,Object>>table=records.computeIfAbsent(c,k->new LinkedHashMap<String,Map<String,Object>>());if(table.containsKey(id))throw new AssertionError("Duplicate create");table.put(id,record);created++;if(failAfterCommit&&created==3){failAfterCommit=false;throw new java.io.IOException("Simulated committed create response timeout");}return copy(record);}
        public void delete(String c,String id,String guid)throws Exception{if(records.getOrDefault(c,Collections.emptyMap()).remove(id)!=null)deleted++;if(failDeleteAfterCommit){failDeleteAfterCommit=false;throw new java.io.IOException("Simulated delete committed but response lost");}}
        public byte[]download(String id,long max){return "fixture".getBytes(StandardCharsets.UTF_8);}
    }
}
